import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { Container, Box, Typography, Button, Table, TableHead, TableRow, TableCell, TableBody, Chip } from '@mui/material';
import axios from 'axios';

const Dashboard = () => {
  const { user, token } = useAuth();
  const navigate = useNavigate();
  const [appointments, setAppointments] = useState([]);

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }

    const fetchAppointments = async () => {
      try {
        let url = '/api/appointments/myappointments';
        if (user.role === 'stylist') {
          url = `/api/appointments/stylist/${user._id}`;
        } else if (user.role === 'admin') {
          url = '/api/appointments/myappointments';
        }

        const res = await axios.get(url, {
          headers: { Authorization: `Bearer ${token}` }
        });
        setAppointments(res.data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchAppointments();
  }, [user, token, navigate]);

  const getStatusColor = (status) => {
    switch (status) {
      case 'confirmed': return 'success';
      case 'completed': return 'info';
      case 'cancelled': return 'error';
      case 'no-show': return 'error';
      default: return 'warning';
    }
  };

  const handleCancelAppointment = async (appointmentId) => {
    if (window.confirm('Are you sure you want to cancel this appointment?')) {
      try {
        await axios.put(`/api/appointments/${appointmentId}`, 
          { status: 'cancelled' },
          { headers: { Authorization: `Bearer ${token}` } }
        );
        setAppointments(appointments.map(apt => 
          apt._id === appointmentId ? { ...apt, status: 'cancelled' } : apt
        ));
      } catch (err) {
        console.error(err);
        alert('Failed to cancel appointment');
      }
    }
  };

  if (!user) return <div>Loading...</div>;

  return (
    <Container maxWidth="lg" sx={{ mt: 4 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h4">Dashboard</Typography>
        <Box>
          <Button variant="outlined" color="secondary" onClick={() => {
            localStorage.removeItem('token');
            navigate('/login');
          }} sx={{ ml: 1 }}>
            Sign Out
          </Button>
        </Box>
      </Box>

      <Box sx={{ mb: 3 }}>
        <Typography variant="h5" gutterBottom>
          Your Appointments
        </Typography>
        {appointments.length === 0 ? (
          <Typography color="text.secondary">You have no upcoming appointments.</Typography>
        ) : (
          <Table sx={{ minWidth: 650 }} aria-label="appointments table">
            <TableHead>
              <TableRow>
                <TableCell>Service</TableCell>
                <TableCell align="right">Date</TableCell>
                <TableCell align="right">Time</TableCell>
                <TableCell align="right">Stylist</TableCell>
                <TableCell align="right">Status</TableCell>
                <TableCell align="right">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {appointments.map((appointment) => (
                <TableRow key={appointment._id}>
                  <TableCell component="th" scope="row">
                    {appointment.service?.name || 'N/A'}
                  </TableCell>
                  <TableCell align="right">
                    {new Date(appointment.date).toLocaleDateString()}
                  </TableCell>
                  <TableCell align="right">
                    {appointment.startTime}
                  </TableCell>
                  <TableCell align="right">
                    {appointment.stylist?.name || 'N/A'}
                  </TableCell>
                  <TableCell align="right">
                    <Chip 
                      label={appointment.status.charAt(0).toUpperCase() + appointment.status.slice(1)}
                      color={getStatusColor(appointment.status)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell align="right">
                    {(appointment.status === 'pending' || appointment.status === 'confirmed') ? (
                      <Button 
                        size="small" 
                        variant="outlined" 
                        color="error" 
                        onClick={() => handleCancelAppointment(appointment._id)}
                      >
                        Cancel
                      </Button>
                    ) : (
                      <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                        {appointment.status === 'completed' ? 'Completed' : 'Cancelled'}
                      </Typography>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </Box>

      <Box sx={{ textAlign: 'center' }}>
        <Button 
          variant="contained" 
          color="primary" 
          sx={{ mx: 1 }}
          onClick={() => navigate('/')}
        >
          Book New Appointment
        </Button>
      </Box>
    </Container>
  );
};

export default Dashboard;
